}
function ag_ti_css_rules($text,$base,&$notices){$text=preg_replace('#/\*.*?\*/#s','',$text);$clean='';$len=strlen($text);for($i=0;$i<$len;$i++){if($text[$i]==='@'){$notices['css-advanced']='Media queries, font imports and CSS at-rules need manual recreation in native device styles.';$depth=0;for(;$i<$len;$i++){if($text[$i]==='{')$depth++;elseif($text[$i]==='}'&&--$depth===0)break;elseif($text[$i]===';'&&$depth===0)break;}continue;}$clean.=$text[$i];}
