function ag_ti_color($value){$v=strtolower(trim($value));$names=array('white'=>'#ffffff','black'=>'#000000','red'=>'#ff0000','blue'=>'#0000ff','green'=>'#008000','gray'=>'#808080','grey'=>'#808080','yellow'=>'#ffff00','orange'=>'#ffa500','transparent'=>'transparent');if(isset($names[$v]))return $names[$v];if(preg_match('/^#[a-f0-9]{3}(?:[a-f0-9]{3})?$/i',$v))return $v;if(preg_match('/^rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/',$v,$m))return sprintf('#%02x%02x%02x',min(255,$m[1]),min(255,$m[2]),min(255,$m[3]));return null;}
function ag_ti_px($value){if(!preg_match('/^(-?\d+(?:\.\d+)?)(px|rem|em|pt)?$/i',trim($value),$m))return null;$unit=strtolower($m[2] ?? 'px');return (float)$m[1]*($unit==='rem'||$unit==='em'?16:($unit==='pt'?4/3:1));}
