    foreach(array('font-size'=>'fontSize','margin-top'=>'marginTop','margin-bottom'=>'marginBottom','border-radius'=>'radius','gap'=>'gap','min-height'=>'minHeight','height'=>'height','border-width'=>'borderWidth') as $from=>$to)if(isset($css[$from])&&($v=ag_ti_px($css[$from]))!==null)$s[$to]=$v;
    if(isset($css['padding'])){$parts=preg_split('/\s+/',trim($css['padding']));$values=array_map('ag_ti_px',$parts);if(!in_array(null,$values,true)){$s['padding']=$values[count($values)===1?0:1];$s['paddingY']=$values[0];}}
    if(isset($css['padding-top'])&&($v=ag_ti_px($css['padding-top']))!==null)$s['paddingY']=$v;if(isset($css['padding-left'])&&($v=ag_ti_px($css['padding-left']))!==null)$s['padding']=$v;
    if(isset($css['text-align'])&&in_array($css['text-align'],array('left','center','right'),true))$s['align']=$css['text-align'];if(isset($css['font-weight']))$s['bold']=$css['font-weight']==='bold'||(is_numeric($css['font-weight'])&&$css['font-weight']>=600);if(isset($css['font-style']))$s['italic']=$css['font-style']==='italic';if(isset($css['box-shadow']))$s['shadow']=$css['box-shadow']==='none'?'none':'soft';
