        $topAnchor=ag_ti_anchor($body->getAttribute('id')) ?: 'imported-top';$link=function($url)use($selected,$topAnchor,&$notices){$url=trim($url);if($url==='')return '';if(substr($url,0,1)==='#')return '#'.(ag_ti_anchor(rawurldecode(substr($url,1))) ?: $topAnchor);if(preg_match('#^(https?://|mailto:|hop://)#i',$url))return ag_pb_link($url);$parts=@parse_url($url);$file=ag_ti_resolve($selected,$url);if($file===$selected)return '#'.(!empty($parts['fragment'])?ag_ti_anchor(rawurldecode($parts['fragment'])):$topAnchor);$notices['local-links']='Links to other template pages or local files need to be connected to imported DreamGrid pages; their buttons were disabled.';return '';};
