            $style=array_merge(array('padding'=>0,'paddingY'=>0,'gap'=>12),$style);$type='section';if(in_array($css['display'] ?? '',array('grid','flex'),true)&&count($children)>1){$type='columns';$columns=0;if(isset($css['grid-template-columns'])&&preg_match('/repeat\(\s*(\d+)/',$css['grid-template-columns'],$m))$columns=(int)$m[1];$style['columns']=max(1,min(6,$columns ?: count($children)));$style['tabletColumns']=min(2,$style['columns']);$style['mobileColumns']=1;}
            if(preg_match('/url\(\s*["\']?([^"\')]+)["\']?\s*\)/',$css['background-image'] ?? $css['background'] ?? '',$bg)){$props['image']=$image($bg[1],$cssBase ?: $selected);if($type==='columns'){$notices['background-columns']='Some column backgrounds need to be reapplied on a containing section.';unset($props['image']);}}
            return array($make($type,$props,$style,$children,$name));
        };
        $blocks=$walk($body,0);if(!$blocks)throw new RuntimeException('No editable page content was found.');$blocks[0]['props']['anchor']=$topAnchor;$title=trim($doc->getElementsByTagName('title')->item(0)->textContent ?? '') ?: pathinfo($selected,PATHINFO_FILENAME);$p=ag_pd_default_page();$p['id']=str_repeat('0',16);$p['title']=$title;$p['builder']=array('version'=>1,'theme'=>array(),'blocks'=>$blocks);$p=ag_pd_normalize($p);$used=ag_pd_page_images($p);$assets=array_intersect_key($assets,array_flip($used));$package=array('format'=>'dreamgrid-page','version'=>1,'page'=>$p,'assets'=>$assets);$json=json_encode($package,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);if(strlen($json)>ag_pd_package_limit())throw new RuntimeException('The converted page exceeds the portable package size limit.');
